export const encoreId = (number: StoryLessonNumber) => `conversational-skills-L7-C5-${number}-${encoreEpisodes[number].skill}-en-v1`;

export function buildEncoreLesson(number: StoryLessonNumber, previous: any = {}, reference?: any) {
  const index = storyLessonNumbers.indexOf(number);
  const lesson = buildEnglishExpressionLesson(number, encoreEpisodes[number], previous, reference, {
    id: encoreId(number), chapterName: 'One Last Encore', pronunciation: encorePronunciation[number],
    setting: 'The fictional Spotlight Works and Apex Entertainment partnership prepares for the Tokyo Sound Festival, with production meetings, an early live venue, a rehearsal studio and the festival stage. Months later, the story ends at Spotlight Works.',
    previousSummary: index === 0 ? fameEpisodes[9].closing : encoreEpisodes[storyLessonNumbers[index - 1]!].closing,
    storyNotes: `${conversationalLanguageInstructions(7)}\nReference: Beyond the Spotlight, Chapter 5: One Last Encore, the final chapter. Owner target TOEIC 550-780 overrides C1-C2 subtitle. Eight episodes use slots 1-4 and 6-9; 5/10 stay dynamic. English only, four expressions, Step B-only pronunciation with exact bold stress, no Part III or extra pronunciation commentary. Objective first, plain situations, separate questions, direct tutor-first roles, short models and no required audience monologue. Private listening, fresh visible reading notes, fixed English feedback, no new artwork, romance or external model calls. Six weeks before fictional festival: main stage, substantial expected live and online audiences without exact counts, festival video crew coordinates with Luis. Quiet Streets first absent from Apex preference; Kai argues, Maya proposes emotional turning point, Natsumi suggests most energetic song next, Apex agrees. Following song is unnamed; do not automatically call it Paper Skyline. Mr. Ishikawa owns an early venue, not necessarily every earlier live house. First audience corrected from twelve to thirteen including him, not fourteen; no debt, asks Kai to offer someone a chance someday. Final rehearsal has blue-to-red cue error from outdated sheet, updated successfully; no actual festival blackout. Night before: Natsumi puts importance in perspective; old Paper Skyline lyric page records desire to be heard. Actual festival fault concerns one audio playback system. Programme already behind, repair needs time. Kai proposes acoustic Quiet Streets, musical director confirms needed microphones/instruments work, festival manager approves, Maya checks comfort, stage manager signals and Kai walks on. Lights dim normally, not a power outage. Audience listens quietly then applauds. Playback repaired before planned set continues, ending Paper Skyline. Manager permits short encore: brief acoustic reprise of Paper Skyline with crowd, not a new song or whole extra concert. Months later both new singles reach wider-than-expected audiences without titles, chart ranks, sales or worldwide fame. Respectful Apex partnership and Spotlight Works independence coexist. Artist development expands to a few independent musicians. Maya receives opportunity to lead creative production, not confirmed acceptance. Unnamed young woman with guitar arrives for meeting, has years of songwriting and doubts. No supplied age, signed contract or guaranteed fame. Kai welcomes and encourages pride in work, remembering early support. She enters studio and plays. End Beyond the Spotlight with gratitude, creative voice and shared purpose; no new crisis, unresolved villain plot, new chapter or sequel cliffhanger.`,
  });
  lesson.storyData.storyTitle = 'Beyond the Spotlight';
  lesson.storyData.characters = [
    { id: 'maya', name: 'Maya Kurose', role: 'main', description: 'Creative producer who supports the setlist compromise, coordinates preparation and adaptation, and later receives a creative leadership opportunity.' },
    { id: 'natsumi', name: 'Natsumi Ito', role: 'supporting', description: 'Talent manager who helps negotiate song order, supports Kai before the festival and announces expanded artist development.' },
    { id: 'jisoo', name: 'Jisoo', role: 'supporting', description: 'Digital strategist who sees new audience opportunities and later supports promotional planning with more manageable schedules.' },
    { id: 'luis', name: 'Luis', role: 'supporting', description: 'Videographer who coordinates with festival video production and helps correct the rehearsal cue-sheet mismatch.' },
    { id: 'kai', name: 'Kai Nakamura', role: 'supporting', description: 'Singer-songwriter who adapts the festival opening, values the people behind his progress and welcomes a new musician in the closing scene.' },
    { id: 'shibata', name: 'Mr. Shibata', role: 'supporting', description: 'Apex representative who presents the festival opportunity and production expectations.' },
    { id: 'hoshino', name: 'Ms. Hoshino', role: 'supporting', description: 'Apex senior producer concerned about audience energy during the setlist debate.' },
    { id: 'ishikawa', name: 'Mr. Ishikawa', role: 'supporting', description: 'Owner of an early venue who recalls listening to Kai and asks him to offer someone else a similar opportunity.' },
    { id: 'new-musician', name: 'New musician', role: 'supporting', description: 'Unnamed woman who arrives with a guitar for an artist development meeting. Kai welcomes her and encourages pride in her own work.' },
  ];
  return { ...lesson, course: 'conversational-skills', level: 7, chapter: 5, lessonNumber: number,
    levelBadge: 'INTERMEDIATE', chapterLabel: 'Chapter 5: One Last Encore', status: previous.status || 'draft',
    overlayColor: previous.overlayColor || '#17252bcc', supportLanguage: 'en', authoringLanguageTarget: 'TOEIC 550-780', authoringLanguageRevision: 'toeic-v1' };
}

export function buildEncoreChapter(reference?: any) {
  return storyLessonNumbers.map(number => buildEncoreLesson(number, {}, reference));
}
